// Shared round-trip cases of the formats node:test suites (a port of
// crates/fontpixel-py/tests/formats_support.py).
//
// Every catalogue format ID has one case: a source font, the typed write
// options (and the equivalent frozen-CLI flags), and the typed read options
// needed to read the output back (and their CLI flags).
// crates/fontpixel-py/tests/data/formats/cli_golden.json holds the SHA-256 of
// every asset the frozen CLI wrote for the case and of the YAFF the CLI
// produced when reading that output back (regenerated by
// regen_cli_golden.py next to it, from the CLI only). The JS tests repeat
// each operation through the WASM binding and compare with those hashes;
// a few cases also run the CLI live (tests/helpers.mjs).
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { REPO } from './helpers.mjs';

export const PY_DATA = path.join(REPO, 'crates', 'fontpixel-py', 'tests', 'data', 'formats');
export const GOLDEN = JSON.parse(readFileSync(path.join(PY_DATA, 'cli_golden.json'), 'utf8'));

export const SOURCES = {
  // Unicode-mapped proportional 3x5 font (102 glyphs).
  uni3: path.join(REPO, 'tests', 'data', 'bdf', '3x5-block.bdf'),
  // The same font with CP437 legacy codes (frozen CLI `charset --to cp437`).
  leg3: path.join(PY_DATA, '3x5-block-cp437.pcf'),
  // Unicode-mapped fixed 5x8 font (472 glyphs).
  uni5: path.join(REPO, 'tests', 'data', 'bdf', 'spleen-5x8.bdf'),
  // The same font with CP437 legacy codes.
  leg5: path.join(PY_DATA, 'spleen-5x8-cp437.pcf'),
};

/** Bytes of a source font. */
export function sourceFile(key) {
  return new Uint8Array(readFileSync(SOURCES[key]));
}

const be16 = (b, at, v) => {
  b[at] = v >> 8;
  b[at + 1] = v & 0xff;
};

// Byte-authored native fixtures, ported from crates/fontpixel/tests/<format>.rs
// (exactly as formats_support.py builds them).
export const NATIVE = {
  daisy() {
    const out = [0x33, 0x9b];
    for (let cp = 33; cp < 125; cp++) {
      if (cp === 96 || cp === 123) continue;
      out.push(66);
      const g = new Array(8).fill(0);
      if (cp === 65) {
        g[0] = 0x80;
        g[1] = 0x40;
        g[6] = 0x20;
      }
      out.push(...g);
    }
    out.push(31, 30, 2);
    return new Uint8Array(out);
  },
  tasprint() {
    const b = new Uint8Array(1920);
    const p = 33 * 20;
    b[p] = 0x80;
    b[p + 1] = 0x40;
    b[p + 12] = 0x20;
    return b;
  },
  hrcg() {
    const b = new Uint8Array(768);
    for (let i = 0; i < 768; i++) b[i] = i % 8 === 0 ? 0x80 : (1 << i % 7) | (i % 2 === 0 ? 128 : 0);
    return b;
  },
  hmzk() {
    const b = new Uint8Array(84);
    b.set([0x48, 0x4d, 0x5a, 0x4b], 0);
    b.fill(0xff, 4, 14);
    b[4] = 1;
    b[14] = 4;
    b[16] = 65;
    b[18] = 66;
    for (let i = 0; i < 64; i++) b[20 + i] = (i * 37) & 0xff;
    return b;
  },
  fbit() {
    const b = new Uint8Array(48);
    b.set([0x66, 0x62, 0x69, 0x74], 2);
    be16(b, 6, 128);
    be16(b, 24, 3);
    be16(b, 26, 3);
    be16(b, 32, 0x817e);
    be16(b, 34, 0x8180);
    be16(b, 36, 1);
    be16(b, 38, 62);
    be16(b, 40, 63);
    be16(b, 42, 2);
    b.set([0xaf, 0x80, 0x72, 0], 44);
    return b;
  },
  hanfont() {
    const out = new Uint8Array(360 * 32);
    for (let slot = 0; slot < 360; slot++) {
      for (let p = 0; p < 32; p++) out[slot * 32 + p] = ((slot * 29 + p * 47) ^ (slot >> 3)) & 0xff;
    }
    return out;
  },
};

/** `raw` with the 3x6 cells of the 3x5-block font (`RawLayout::new(3, 6)`). */
export const RAW_LAYOUT = Symbol('raw_layout(3, 6)');

const VECTOR = { outline: { flavor: 'cff' } };

function makeCase({ source = 'uni3', write = {}, cli = [], read = {}, cliRead = [], sourceRead = {}, cliSourceRead = [] } = {}) {
  return { source, write, cli, read, cliRead, sourceRead, cliSourceRead };
}

export const CASES = {
  hex: makeCase({
    write: { geometry: { height: 6, descent: 1 } },
    cli: ['--hex-height', '6', '--hex-descent', '1'],
    read: { height: 6, descent: 1 },
    cliRead: ['--hex-height', '6', '--hex-descent', '1'],
  }),
  hzk: makeCase({ write: { preset: 'asc16' }, cli: ['--hzk-preset', 'asc16'], read: { preset: 'asc16' }, cliRead: ['--hzk-preset', 'asc16'] }),
  hbf: makeCase({ source: 'uni5' }),
  kbits: makeCase({ source: 'uni5' }),
  fzx: makeCase({ source: 'leg3', write: { tracking: 1 }, cli: ['--fzx-tracking', '1'] }),
  palm: makeCase({ source: 'leg5' }),
  catalyst: makeCase({ source: 'leg5' }),
  dashen: makeCase({ source: 'leg5' }),
  gpi: makeCase({ source: 'leg5' }),
  writeon: makeCase({ source: 'leg3', write: { cell_size: [8, 14] }, cli: ['--native-cell-width', '8', '--native-cell-height', '14'] }),
  ssfn: makeCase({ source: 'uni5' }),
  pfr: makeCase({ source: 'leg5' }),
  cpi: makeCase({ source: 'leg3', write: { code_page: 437 }, cli: ['--cpi-code-page', '437'] }),
  raw: makeCase({ read: { layout: RAW_LAYOUT }, cliRead: ['--raw-width', '3', '--raw-height', '6'] }),
  woff: makeCase({ write: VECTOR }),
  woff2: makeCase({ write: VECTOR }),
  ttc: makeCase({ write: VECTOR }),
  'vector-raster': makeCase({ write: VECTOR }),
  hanfont: makeCase({
    source: 'native',
    sourceRead: { mode: 'components' },
    cliSourceRead: ['--hanfont-read-mode', 'components'],
    read: { mode: 'components' },
    cliRead: ['--hanfont-read-mode', 'components'],
  }),
};
/** Options the CLI applies even without flags (it always configures OpenType output). */
export const CLI_IMPLICIT = Object.fromEntries(['woff', 'woff2', 'ttc', 'vector-raster'].map((f) => [f, VECTOR]));
for (const fid of ['daisy', 'tasprint', 'hrcg', 'hmzk', 'fbit']) CASES[fid] = makeCase({ source: 'native' });
// Formats the CLI converts from the legacy-coded 3x5 font but not the Unicode one.
const LEGACY3 = `cpi nfnt iigs gem vfont drcs bbc chiwriter comfont consoleet dosstart drhalo edwin
geos grasp hppcl lisa mgtk mkwinfont pcgeos pcr pilfont plus3dos polyprint printshop pxl
riscos signum wsfont wyse xbin xerox cybiko sbf`.split(/\s+/);
for (const fid of LEGACY3) CASES[fid] ??= makeCase({ source: 'leg3' });

