/** The case of `fid` (default: the Unicode 3x5 font, no options), with the raw layout resolved. */
export function caseOf(fp, fid) {
  const c = CASES[fid] ?? makeCase();
  if (c.read.layout === RAW_LAYOUT) return { ...c, read: { layout: fp.formats.raw.rawLayout(3, 6) } };
  return c;
}

/** Source bytes of `fid`'s case. */
export function sourceBytes(fid) {
  const c = CASES[fid] ?? makeCase();
  return c.source === 'native' ? NATIVE[fid]() : sourceFile(c.source);
}

/** `font.<first extension>` (or `font`) of a FormatStatus. */
export function primaryName(status) {
  const exts = status.format.extensions;
  return exts.length ? `font.${exts[0]}` : 'font';
}

/** `{path: Uint8Array}` of a Written or OutputBundle. */
export function assetsOf(written) {
  const bundle = written.output ?? written;
  return Object.fromEntries(bundle.assets.map((a) => [a.path, a.data]));
}

/** SHA-256 (hex) of bytes. */
export function sha(data) {
  return createHash('sha256').update(data).digest('hex');
}

/** `{path: sha256}` of a Written or OutputBundle. */
export function hashes(written) {
  return Object.fromEntries(Object.entries(assetsOf(written)).map(([k, v]) => [k, sha(v)]));
}

/** Plain value with object keys sorted (deep), for order-insensitive comparison. */
export function sorted(value) {
  if (Array.isArray(value)) return value.map(sorted);
  if (value && typeof value === 'object' && !(value instanceof Uint8Array)) {
    return Object.fromEntries(Object.keys(value).sort().map((k) => [k, sorted(value[k])]));
  }
  return value;
}

/** Whether this build compiled format `fid`. */
export function enabled(fp, fid) {
  return fp.listFormats().some((s) => s.format.id === fid && s.format.feature_enabled);
}

/** The direct namespace serving `fid`. */
export function namespaceOf(fp, fid) {
  for (const name of fp.formats.modules()) {
    if (name !== 'x11' && fp.formats[name].formatIds().includes(fid)) return [name, fp.formats[name]];
  }
  throw new Error(`no namespace serves ${fid}`);
}

/**
 * Call `fn(first, bag, ...rest)`, dropping option keys the function rejects
 * as unknown (`unknown option \`key\``), so one call site serves every direct
 * reader/writer shape. Returns `[result, keys actually accepted]`.
 */
export function callAdaptive(fp, fn, first, bag, ...rest) {
  const options = { ...bag };
  for (;;) {
    try {
      return [fn(first, options, ...rest), Object.keys(options)];
    } catch (e) {
      const m = e instanceof fp.InvalidInputError && /unknown option `(\w+)`/.exec(e.message);
      if (!m || !(m[1] in options)) throw e;
      delete options[m[1]];
    }
  }
}
